/* @lc app=leetcode id=3836 lang=kotlin */ class Solution { fun maxScore(nums1: IntArray, nums2: IntArray, k: Int): Long = (1..k).fold(Array(nums1.size + 1) { LongArray(nums2.size + 1) }) { prev, t -> Array(nums1.size + 1) { LongArray(nums2.size + 1) { Long.MIN_VALUE / 4 } }.also { cur -> (1..nums1.size).forEach { i -> (1..nums2.size).forEach { j -> cur[i][j] = maxOf(cur[i - 1][j], cur[i][j - 1], if (prev[i - 1][j - 1] > Long.MIN_VALUE / 8) prev[i - 1][j - 1] + nums1[i - 1].toLong() * nums2[j - 1] else Long.MIN_VALUE / 4) } } } }[nums1.size][nums2.size] }